const $=id=>document.getElementById(id),num=n=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:0}),pct=n=>(Number(n)*100).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+'%',dec=n=>Number(n).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,page=0,filtered=[];
function players(){const q=$('playerSearch').value.toLowerCase();const a=data.players.filter(r=>r[0].toLowerCase().includes(q)&&(!$('minimum').checked||+r[2]>=10)).sort((a,b)=>+b[$('sort').value]-+a[$('sort').value]);$('playerCount').textContent=a.length+' jogadores';$('players').innerHTML=a.map(r=>'<tr>'+[esc(r[0]),num(r[2]),num(r[3]),pct(r[6]),num(r[7]),num(r[13]),dec(r[9]),pct(r[10])].map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="8" class="empty">Nenhum jogador encontrado.</td></tr>'}
function maps(){let t=$('mapTeam').value;let a=data.maps.map(r=>{let rows=data.battles.filter(b=>b[4]===r[0]&&(t==='all'||b[1].toLowerCase()===t));let wins=rows.filter(b=>b[2]==='Vitória').length,losses=rows.filter(b=>b[2]==='Derrota').length;return {name:r[0],games:rows.length,wins,losses,rate:rows.length?wins/rows.length:0}}).sort((a,b)=>b.rate-a.rate);$('mapchart').innerHTML=a.map(r=>'<div class="maprow"><span>'+esc(r.name)+'</span><div><div class="bar"><i style="width:'+r.rate*100+'%"></i></div><small>'+r.games+' batalhas · <span class="positive">'+r.wins+' vitórias</span> · <span class="negative">'+r.losses+' derrotas</span></small></div><b>'+pct(r.rate)+'</b></div>').join('')}
function battles(reset=true){if(reset)page=0;let q=$('battleSearch').value.toLowerCase();filtered=data.battles.filter(r=>(r[6]+' '+r[4]).toLowerCase().includes(q)&&(!$('teamFilter').value||r[1]===$('teamFilter').value)&&(!$('resultFilter').value||r[2]===$('resultFilter').value));let pages=Math.max(1,Math.ceil(filtered.length/15));page=Math.min(page,pages-1);$('battleCount').textContent=filtered.length+' partidas detalhadas';$('battles').innerHTML=filtered.slice(page*15,page*15+15).map(r=>{let dt=r[0].split(' '),date=dt[0].split('-').reverse().join('/');return '<tr><td>'+date+' · '+dt[1].slice(0,5)+'</td><td>'+esc(r[1])+'</td><td class="'+(r[2]==='Vitória'?'positive':'negative')+'">'+esc(r[2])+'</td><td class="'+(+r[3]>0?'positive':+r[3]<0?'negative':'')+'">'+(+r[3]>0?'+':'')+esc(r[3])+'</td><td>'+esc(r[4])+'</td><td>'+esc(r[6])+'</td></tr>'}).join('')||'<tr><td colspan="6" class="empty">Nenhuma batalha encontrada.</td></tr>';$('page').textContent='Página '+(page+1)+' de '+pages;$('prev').disabled=page===0;$('next').disabled=page>=pages-1}
fetch('data.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{data=d;players();maps();battles();$('weapons').innerHTML=[['Bateria principal',601],['Torpedos',70],['Bateria secundária',41],['Aeronaves',0],['Abalroamento',36],['Sem classificação',84]].map(r=>'<div style="margin:12px 0"><div class="team"><span>'+r[0]+'</span><span>'+num(r[1])+' · '+pct(r[1]/832)+'</span></div><div class="bar" style="margin:6px 0"><i style="background:var(--gold);width:'+r[1]/832*100+'%"></i></div></div>').join('');renderDashboard(d);['playerSearch','sort','minimum'].forEach(id=>$(id).addEventListener('input',players));$('mapTeam').addEventListener('change',maps);['battleSearch','teamFilter','resultFilter'].forEach(id=>$(id).addEventListener('input',()=>battles()));$('prev').onclick=()=>{page--;battles(false)};$('next').onclick=()=>{page++;battles(false)}}).catch(()=>{$('playerCount').textContent='Não foi possível carregar os dados. Atualize a página para tentar novamente.'});
